160→func isSeedDiff(oldSeed, newSeed []string) bool {
161→	if len(oldSeed) != len(newSeed) {
162→		return true
163→	}
164→
165→	isMissMatch := false
166→	for _, o := range oldSeed {
167→		isMatch := false
168→		for _, n := range newSeed {
169→			if o == n {
170→				isMatch = true
171→				break
172→			}
173→		}
174→		if !isMatch {
175→			isMissMatch = true
176→			break
177→		}
178→	}
179→	if isMissMatch {
180→		return true
181→	}
182→
183→	return false
184→}
