104→func ConvertSearchQueryToRedisKey(query map[string]string) (key string) {
105→	valueKey := make([]string, 0)
106→	for i := 0; i < len(searchQueryFields); i++ {
107→		if isMultiValueField(searchQueryFields[i]) {
108→			format1 := formatSymbolSort(",", query[searchQueryFields[i]])
109→			format2 := formatSymbolSort("|", format1)
110→			format3 := formatSymbolSort("^", format2)
111→			valueKey = append(valueKey, format3)
112→		} else {
113→			valueKey = append(valueKey, query[searchQueryFields[i]])
114→		}
115→	}
116→
117→	h1 := sha1.New()
118→	h1.Write([]byte(strings.Join(valueKey, ":")))
119→
120→	b2 := base64.StdEncoding.EncodeToString([]byte(query["keyword"]))
121→	suffixKey := ""
122→	if len(b2) > 20 {
123→		suffixKey = b2[:20]
124→	} else {
125→		suffixKey = b2
126→	}
127→	key = fmt.Sprintf("search:%x:%s", h1.Sum(nil), suffixKey)
128→	return
129→}
